<?php
include_once './_common.php';nl_require_permission('news_manage');$t=nl_table('news');
if($_SERVER['REQUEST_METHOD']==='POST'){nl_verify_csrf();$action=nl_post_str('action');if($action==='add'){$title=substr(nl_post_str('title'),0,500);$source=substr(nl_post_str('source_name'),0,150);$urlRaw=nl_post_str('source_url');$url=nl_safe_external_url($urlRaw);$cat=substr(nl_post_str('category'),0,100);$ctype=substr(nl_post_str('content_type'),0,100);$published=nl_post_str('published_at');if(!$title||!$url)alert('제목과 올바른 http/https 출처 URL을 입력해 주세요.');$ts=$published?strtotime($published):false;$pub=$ts?"'".date('Y-m-d H:i:s',$ts)."'":'NULL';$vals=array_map('nl_sql_escape',array($title,$source,$url,$cat,$ctype));$now=nl_now();sql_query("INSERT INTO {$t} (title,source_name,source_url,published_at,category,content_type,is_active,created_at,updated_at) VALUES ('{$vals[0]}','{$vals[1]}','{$vals[2]}',{$pub},'{$vals[3]}','{$vals[4]}',1,'{$now}','{$now}') ON DUPLICATE KEY UPDATE title=VALUES(title),source_name=VALUES(source_name),published_at=VALUES(published_at),category=VALUES(category),content_type=VALUES(content_type),is_active=1,updated_at=VALUES(updated_at)",false);nl_audit('news_save','news',$url);goto_url(nl_url('news-manage.php'));}if($action==='toggle'){$id=(int)nl_post_str('id','0');$active=(int)nl_post_str('active','0')?1:0;sql_query("UPDATE {$t} SET is_active={$active},updated_at='".nl_now()."' WHERE id={$id}",false);nl_audit('news_toggle','news',$id,array('active'=>$active));goto_url(nl_url('news-manage.php'));}}
$res=sql_query("SELECT * FROM {$t} ORDER BY COALESCE(published_at,created_at) DESC LIMIT 300",false);$rows=array();if($res)while($r=sql_fetch_array($res))$rows[]=$r;nl_enqueue_assets();$g5['title']='뉴스 관리';include_once G5_PATH.'/head.php';
?>
<div class="nl-page"><div class="nl-page-head"><p class="nl-kicker">콘텐츠 운영</p><h1>뉴스 관리</h1><p>사용자 화면에는 내부 수집 기술을 노출하지 않고 출처와 기사 정보만 제공합니다.</p></div><details class="nl-panel nl-panel--spaced"><summary><strong>뉴스 직접 추가</strong></summary><form method="post" class="nl-form nl-form--nested"><?php echo nl_csrf_field(); ?><input type="hidden" name="action" value="add"><div class="nl-field"><label>제목</label><input name="title" required maxlength="500"></div><div class="nl-field-row"><div class="nl-field"><label>출처</label><input name="source_name" maxlength="150"></div><div class="nl-field"><label>게시 시각</label><input type="datetime-local" name="published_at"></div></div><div class="nl-field"><label>원문 URL</label><input type="text" name="source_url" placeholder="https://..." required></div><div class="nl-field-row"><div class="nl-field"><label>분류</label><input name="category"></div><div class="nl-field"><label>유형</label><input name="content_type" placeholder="언론기사 / 공식자료"></div></div><button class="nl-btn nl-btn--primary" type="submit">추가</button></form></details><div class="nl-table-wrap"><table class="nl-table"><thead><tr><th>상태</th><th>기사</th><th>출처</th><th>일자</th><th>관리</th></tr></thead><tbody><?php foreach($rows as $r){ ?><tr><td><?php echo $r['is_active']?'<span class="nl-badge nl-badge--approved">노출</span>':'<span class="nl-badge nl-badge--suspended">숨김</span>'; ?></td><td><?php echo nl_h($r['title']); ?></td><td><?php $u=nl_safe_external_url($r['source_url']);if($u){ ?><a class="nl-source-link" href="<?php echo nl_h($u); ?>" target="_blank" rel="noopener noreferrer"><?php echo nl_h($r['source_name']?:'원문'); ?></a><?php } ?></td><td><?php echo nl_h($r['published_at']?substr($r['published_at'],0,10):''); ?></td><td><form method="post"><?php echo nl_csrf_field(); ?><input type="hidden" name="action" value="toggle"><input type="hidden" name="id" value="<?php echo (int)$r['id']; ?>"><input type="hidden" name="active" value="<?php echo $r['is_active']?0:1; ?>"><button class="nl-btn nl-btn--small" type="submit"><?php echo $r['is_active']?'숨김':'복원'; ?></button></form></td></tr><?php } ?></tbody></table></div></div>
<?php include_once G5_PATH.'/tail.php'; ?>
